\label{thm:allannuli}
For every $0<r<R$ and every $\Lambda\ge0$,
\begin{equation}\label{eq:allannulicount}
 N_A\left(\Lambda\right)>\frac{R^2-r^2}{4}\Lambda.
\end{equation}
Consequently,
\begin{equation}\label{eq:allannulieigenvalue}
 \nu_k\left(A_{r,R}\right)\le\frac{4k}{R^2-r^2},
 \,\,\, k\ge1.
\end{equation}

\label{lem:radial}
For every integer $m\ge0$ and integer $n\ge0$,
\begin{equation*}
 \lambda_{m,n}\le\frac{\pi^2n^2}{h^2}
             +\frac{m^2+3/4}{r^2}.
\end{equation*}
For $n=0$ the term $3/\left(4r^2\right)$ can be omitted.

\label{lem:sum}
Let $\left\lfloor a\right\rfloor$ denote the greatest integer not exceeding $a$.
For every $a>0$,
\begin{equation}\label{eq:sum}
 S\left(a\right):=\sum_{n=0}^{\left\lfloor a\right\rfloor}
       \sqrt{1-\left(n/a\right)^2}
 \ge\frac\pi4 a+1-\frac\pi4.
\end{equation}
The constant $1-\pi/4$ is optimal in this inequality valid for all $a$.

\label{lem:exactphasecount}
Let $n_m\left(t^2\right)$ be the radial Neumann counting function in integer angular
order $m\ge0$, including its zero eigenvalue when $m=0$. For every $t>0$,
\begin{equation}\label{eq:exactphasecount}
 n_m\left(t^2\right)=\left\lfloor
 \frac{\varphi_m\left(Rt\right)-\varphi_m\left(t\right)}\pi\right\rfloor+1.
\end{equation}

\label{lem:radiusendpoints}
If $0<a\le b<1$ and $0<u\le v$, then, for every
$\left(\rho,X\right)\in\left[a,b\right]\times\left[u,v\right]$,
\[
 n_m\left(\rho,X\right)\ge
 \min\left\{n_m\left(a,u\right),n_m\left(b,u\right)\right\}\,\,\,\left(m=0,1,2,\ldots\right).
\]
Consequently any certified lower bounds $L_m\left(a,u\right)$ and $L_m\left(b,u\right)$
for the two endpoint counts give the uniform lower bound
\begin{equation}\label{eq:boxcount}
 N_\rho\left(X^2\right)\ge
 \min\left\{L_0\left(a,u\right),L_0\left(b,u\right)\right\}
 +2\sum_{m=1}^{\left\lfloor u\right\rfloor}
       \min\left\{L_m\left(a,u\right),L_m\left(b,u\right)\right\}.
\end{equation}

\label{lem:diskanalyt_surplus}
For every $X\ge\sqrt{32}$,
\begin{equation}\label{eq:diskanalyt_surplus}
 \mathcal N_B\left(X\right)-1\ge\frac{X^2}{4}.
\end{equation}
